function isBadgeEarned(badge, streak, totalSessions) {
    switch(badge.id){
        case 'first_session':
            return totalSessions >= 1;
        case 'streak_3':
        case 'streak_7':
        case 'streak_30':
            return streak >= badge.requirement;
        case 'sessions_10':
        case 'sessions_50':
            return totalSessions >= badge.requirement;
        case 'perfect_score':
        case 'all_categories':
            // These require more complex logic; default to locked for now
            return false;
        default:
            return false;
    }
}
